// Enterprise management types (generated by engineering-platform frontend-enterprise-management asset)
// Stable TS models for User/Role/Permission/Department/Menu/Dictionary/OperationLog.
//
// API Boundary ID String Contract: domain IDs (Snowflake, > Number.MAX_SAFE_INTEGER)
// cross the JSON boundary as strings. Frontend NEVER stores them as number.
// Numeric metrics (total/page/size/sort) stay number.

export type EntityId = string;

// ---- paging (backend PageResult<T>: { items, total, page, size }) ----

export interface PageResult<T> {
  items: T[];
  total: number;
  page: number;
  size: number;
}

// ---- user ----

export interface User {
  id: EntityId;
  username: string;
  enabled: boolean;
  departmentId: EntityId | null;
  roleIds: EntityId[];
  createdAt: string;
}

export interface UserCreateRequest {
  username: string;
  initialPassword?: string;
  departmentId?: EntityId | null;
  roleIds?: EntityId[];
}

export interface UserUpdateRequest {
  username?: string;
  departmentId?: EntityId | null;
  roleIds?: EntityId[];
}

export interface UserCreateResult {
  user: User;
  initialPassword: string;
}

// ---- role ----

export type DataScope = 'ALL' | 'DEPARTMENT_AND_CHILDREN' | 'DEPARTMENT' | 'SELF';

export interface Role {
  id: EntityId;
  code: string;
  name: string;
  enabled: boolean;
  dataScope: DataScope;
  permissionIds: EntityId[];
  createdAt: string;
}

export interface RoleCreateRequest {
  code: string;
  name?: string;
  dataScope?: DataScope;
  permissionIds?: EntityId[];
}

export interface RoleUpdateRequest {
  name?: string;
  dataScope?: DataScope;
  permissionIds?: EntityId[];
}

// ---- permission ----

export interface Permission {
  id: EntityId;
  code: string;
  name: string;
  createdAt: string;
  updatedAt: string;
}

// ---- department ----

export interface Department {
  id: EntityId;
  parentId: EntityId | null;
  code: string;
  name: string;
  enabled: boolean;
  sort: number;
  createdAt: string;
  updatedAt: string;
}

export interface DepartmentNode {
  department: Department;
  children: DepartmentNode[];
}

// ---- menu ----

export type MenuType = 'DIRECTORY' | 'MENU' | 'ACTION';

export interface Menu {
  id: EntityId;
  parentId: EntityId | null;
  code: string;
  name: string;
  type: MenuType;
  path: string | null;
  permissionCode: string | null;
  enabled: boolean;
  sort: number;
  createdAt: string;
  updatedAt: string;
}

export interface MenuNode {
  menu: Menu;
  children: MenuNode[];
}

// ---- dictionary ----

export interface DictionaryType {
  id: EntityId;
  code: string;
  name: string;
  enabled: boolean;
  description: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface DictionaryItem {
  id: EntityId;
  typeId: EntityId;
  value: string;
  label: string;
  enabled: boolean;
  sort: number;
  description: string | null;
  createdAt: string;
  updatedAt: string;
}

// ---- operation log ----

export interface OperationLog {
  id: EntityId;
  userId: EntityId | null;
  operation: string;
  resourceType: string;
  resourceId: EntityId | null;
  result: string;
  requestId: string | null;
  correlationId: string | null;
  method: string | null;
  path: string | null;
  occurredAt: string;
}
